import { fieldNotesView } from './field-notes.js';
import { mountPremiumMotion } from './premium-motion.js';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = { play:'m9 5 11 7-11 7V5Z', arrow:'m5 12 14 0m-6-6 6 6-6 6', back:'m14 5-7 7 7 7', close:'m6 6 12 12M6 18 18 6', plus:'M12 5v14M5 12h14', minus:'M5 12h14', layers:'m3 8 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5m-18 5 9 5 9-5', route:'M5 18c0-6 14-3 14-10M5 18h.01M19 6h.01', clock:'M12 8v5l3 2m6-3a9 9 0 1 1-18 0 9 9 0 0 1 18 0', check:'m5 12 4 4L19 6', menu:'M4 7h16M4 12h16M4 17h16', heart:'M20.5 5.5a5 5 0 0 0-7 0L12 7l-1.5-1.5a5 5 0 0 0-7 7L12 21l8.5-8.5a5 5 0 0 0 0-7Z', info:'M12 11v6m0-10h.01m9 5a9 9 0 1 1-18 0 9 9 0 0 1 18 0', chevron:'m9 5 7 7-7 7', chevrondown:'m5 9 7 7 7-7', target:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5', journal:'M5 3h14v18H5zM9 7h6m-6 5h6m-6 5h3', logout:'M14 4H5v16h9m-3-8h10m-4-4 4 4-4 4', cloud:'M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11-1 5 5 0 0 1 0 11', refresh:'M20 11a8 8 0 0 0-14-5L3 9m0-5v5h5m-4 4a8 8 0 0 0 14 5l3-3m0 5v-5h-5', mountain:'m2 20 7-14 5 8 3-5 5 11H2Z', flag:'M6 21V3h12l-3 5 3 5H6', settings:'M4 7h16M4 17h16M9 4v6m6 4v6' };
const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.info}"/></svg>`;
const logo = `<svg class="brand-symbol" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 25 11 7h5L8 25m9 0 8-18h4l-8 18"/></svg>`;
const duration = seconds => seconds == null ? '—' : `${Math.floor(Math.round(seconds)/60)}:${String(Math.round(seconds)%60).padStart(2,'0')}`;
const paceText = seconds => seconds == null || !Number.isFinite(seconds) ? '—' : duration(seconds);
const distance = metres => metres == null ? '—' : (metres/1000).toFixed(2);
const dateText = date => date ? new Date(date+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}) : 'Date to confirm';
const round = value => value == null ? '—' : String(Math.round(value));
const params = new URLSearchParams(location.search);
document.documentElement.classList.toggle('large-text',['large','largest'].includes(params.get('text')));
document.documentElement.classList.toggle('largest-text',params.get('text')==='largest');
document.documentElement.classList.toggle('reduce-motion',params.get('motion')==='reduce');
const reducedMotion = () => document.documentElement.classList.contains('reduce-motion') || matchMedia('(prefers-reduced-motion: reduce)').matches;
const state = {direction:'field-notes',scenario:params.get('scenario')||'normal',activityId:params.get('activity')||null,selected:null,expandedBlocks:false,series:'pace',cursor:null,zoom:1,feedbackError:'',pending:false};
let payload, activity, draft, premiumMotion;
let routeCache={records:null,value:null},chartCache={records:null,value:null,series:null,width:null},pointerFrame=0,pointerX=0;
try{if(localStorage.getItem('mfa-visual-motion')==='off')document.documentElement.classList.add('reduce-motion');}catch{}
const emptyDraft = () => ({answers:{effort:null,breathing:null,discomfort:null,finish:null},location:null,note:'',context:[],complete:false,pending:false});
function readDraft() {try{return {...emptyDraft(),...JSON.parse(localStorage.getItem('mfa-prototype:'+activity.id)||'null')};}catch{return emptyDraft();}}
function storeDraft() {try{localStorage.setItem('mfa-prototype:'+activity.id,JSON.stringify(draft));}catch{$('#announcer').textContent='Browser storage is unavailable. Keep this preview open to retain your answers.';}}
function currentActivity() {const original=payload.activities.find(x=>x.id===state.activityId)||payload.activities.find(x=>x.id===payload.defaultId);return state.scenario==='partial'?{...original,hr:null,maxHr:null,records:original.records.map(r=>({...r,hr:null,lat:null,lon:null})),blocks:original.blocks.map(b=>({...b,hr:null}))}:original;}
function setActivity(id){state.activityId=id;state.selected=null;state.expandedBlocks=false;state.cursor=null;state.zoom=1;state.feedbackError='';activity=currentActivity();draft=readDraft();state.pending=draft.pending;params.set('activity',id);params.set('direction',state.direction);history.pushState(null,'',location.pathname+'?'+params);render();window.scrollTo({top:0,behavior:'instant'});}
function summaryPace(){return activity.displayedPace??(activity.distance>0?activity.timer/activity.distance*1000:null);}
function metric(value,unit,label,small=''){return `<div class="metric"><div class="metric-value">${value}<span>${unit}</span></div><div class="metric-label">${label}</div>${small?`<div class="metric-hint">${small}</div>`:''}</div>`;}
function stats(){return `<section class="metric-rail" aria-label="Session summary">${metric(distance(activity.distance),'km','Distance')}${metric(duration(activity.timer??activity.running??activity.moving),'',activity.timer!=null?'Timer time':activity.running!=null?'Running time':'Moving time')}${metric(paceText(summaryPace()),'/km','Average pace')}${metric(round(activity.hr),'bpm','Average heart rate',activity.hr==null?'Not recorded':'')}${metric(round(activity.elevationGain),'m','Elevation gain')}</section>`;}
function routeGeometry(){
  if(routeCache.records===activity.records)return routeCache.value;
  const coords=activity.records.filter(r=>r.lat!==null&&r.lon!==null);
  if(!coords.length){routeCache={records:activity.records,value:null};return null;}
  const latitude=coords.reduce((sum,r)=>sum+r.lat,0)/coords.length;
  const cos=Math.cos(latitude*Math.PI/180);
  const xx=coords.map(r=>r.lon*cos),yy=coords.map(r=>-r.lat);
  const minX=Math.min(...xx),maxX=Math.max(...xx),minY=Math.min(...yy),maxY=Math.max(...yy);
  const scale=Math.min(460/Math.max(maxX-minX,.00001),240/Math.max(maxY-minY,.00001));
  const cx=(minX+maxX)/2,cy=(minY+maxY)/2;
  const point=r=>({x:320+(r.lon*cos-cx)*scale,y:180+(-r.lat-cy)*scale});
  const path=(first=0,last=activity.records.length-1)=>{let d='',drawing=false;for(let i=first;i<=last;i++){const r=activity.records[i];if(r.lat===null||r.lon===null||(i>first&&r.t-activity.records[i-1].t>30)){drawing=false;if(r.lat===null||r.lon===null)continue;}const p=point(r);d+=`${drawing?'L':'M'}${p.x.toFixed(2)},${p.y.toFixed(2)} `;drawing=true;}return d;};
  const value={point,path,first:coords[0],last:coords.at(-1),scaleMetres:80/scale*111320};routeCache={records:activity.records,value};return value;
}
function mapSvg(name='main'){
  const g=routeGeometry();if(!g)return '';
  const first=g.point(g.first),last=g.point(g.last);const selected=state.selected!==null?activity.blocks[state.selected]:null;
  const cursor=state.cursor==null?null:activity.records[state.cursor];const cp=cursor?.lat!=null&&cursor?.lon!=null?g.point(cursor):null;
  return `<svg viewBox="0 0 640 360" role="img" aria-label="Recorded GPS route${selected?`, time block ${selected.index+1} highlighted`:''}"><defs><pattern id="grid-${name}" width="80" height="60" patternUnits="userSpaceOnUse"><path d="M80 0H0V60" fill="none" stroke="currentColor" stroke-opacity=".09" stroke-width="1"/><circle cx="0" cy="0" r="1.5" fill="currentColor" opacity=".18"/></pattern></defs><rect width="640" height="360" fill="url(#grid-${name})"/><g data-route-layer transform="translate(320 180) scale(${state.zoom}) translate(-320 -180)"><path class="route-underlay" d="${g.path()}"/><path class="route-line ${selected?'route-muted':''}" d="${g.path()}"/>${selected?`<path class="route-line selected-route" d="${g.path(selected.first,selected.last)}"/>`:''}<circle class="start-halo" cx="${first.x}" cy="${first.y}" r="10"/><circle class="start-dot" cx="${first.x}" cy="${first.y}" r="4"/><circle class="end-halo" cx="${last.x}" cy="${last.y}" r="9"/><circle class="end-dot" cx="${last.x}" cy="${last.y}" r="3"/>${cp?`<circle class="cursor-halo" cx="${cp.x}" cy="${cp.y}" r="10"/><circle class="cursor-dot" cx="${cp.x}" cy="${cp.y}" r="4"/>`:''}</g><g class="map-scale" transform="translate(0,-230)"><path d="M32 321v7h80v-7"/><text x="32" y="312">≈ ${Math.round(g.scaleMetres/state.zoom/10)*10} m</text></g><g class="north-arrow" transform="translate(-16,38)"><path d="m601 62 7-19 7 19-7-5-7 5Z"/><text x="608" y="31" text-anchor="middle">N</text></g></svg>`;
}
function routePanel(){
  const hasGPS=Boolean(routeGeometry());
  return `<section class="route-panel ${hasGPS?'':'route-unavailable'}" aria-label="Activity route"><div class="map-topline"><span>${icon('route')} ${hasGPS?'Recorded route':'Route'}</span><button class="icon-button" data-action="source" aria-label="Route source and method">${icon('info')}</button></div>${hasGPS?`<div class="route-svg">${mapSvg()}</div><div class="map-bottom"><span class="map-legend"><i></i>Start <b></b>Finish</span><span class="route-selection">${state.selected===null?'Full activity':`Time block ${state.selected+1}`}</span><div class="map-controls"><button class="icon-button" data-action="zoom-out" aria-label="Zoom route out">${icon('minus')}</button><button class="icon-button" data-action="zoom-in" aria-label="Zoom route in">${icon('plus')}</button><button class="icon-button" data-action="fit-route" aria-label="Fit full route">${icon('target')}</button></div></div><span class="route-caption">${activity.records.find(r=>r.lat!==null&&r.lon!==null)?.t>0?`GPS from ${duration(activity.records.find(r=>r.lat!==null&&r.lon!==null).t)} · outline only`:'GPS outline · no basemap'}</span>`:`<div class="no-route-visual">${icon('route')}<h3>${activity.sourceFile==='Owner-supplied screenshots'?'No GPS in this import':'No GPS recorded'}</h3><p>${activity.sourceFile==='Owner-supplied screenshots'?'Your summary and splits are preserved from the screenshots.':'Your session details still have their place.'}</p></div>`}</section>`;
}
function observationPanel(){return `<section class="observation"><div class="section-kicker">${icon('journal')} Session observation</div><h2>${escape(activity.observation.title)}</h2><p>${escape(activity.observation.evidence)}</p><button class="text-button" data-action="method">How this is calculated ${icon('plus')}</button></section>`;}
function quickCard(){const count=Object.values(draft.answers).filter(x=>x!==null).length;return `<section class="quick-card"><div class="quick-title">${icon('journal')}<span>Your check-in</span><span class="answer-count">${draft.complete?'Complete':`${count} / 4`}</span></div><h2>${draft.complete?'The context is yours.':'How did it feel?'}</h2><p>Effort, breathing, discomfort and finish.<br>A little context for the next run.</p><button class="primary-button" data-action="checkin">${draft.complete?'Edit check-in':'Quick check-in'} ${icon(draft.complete?'check':'arrow')}</button><span class="small-copy">Usually about 30 seconds</span></section>`;}
function seriesValue(row){if(state.series==='heart')return row.hr;if(state.series==='elevation')return row.elevation;return row.speed>0?1000/row.speed:null;}
const seriesName=()=>state.series==='heart'?'Heart rate':state.series==='elevation'?'Elevation':'Pace';
function chartReadout(){const block=state.selected===null?null:activity.blocks[state.selected];return {time:block?`${duration(block.start)} – ${duration(block.end)}`:'Full session',value:state.series==='pace'?paceText(block?block.pace:summaryPace())+' /km':state.series==='heart'?round(block?block.hr:activity.hr)+' bpm':'Recorded altitude'};}
function chartModel(){
  if(chartCache.records===activity.records&&chartCache.series===state.series&&chartCache.width===innerWidth)return chartCache.value;
  const values=activity.records.map(seriesValue).filter(x=>x!==null&&Number.isFinite(x));if(!values.length)return null;
  let min=Math.min(...values),max=Math.max(...values);if(max===min){min-=1;max+=1;}const padding=(max-min)*.12;min-=padding;max+=padding;
  const end=activity.records.at(-1).t||1;
  const left=innerWidth<=700?90:48,span=598-left;
  const x=r=>left+r.t/end*span;
  const y=value=>state.series==='pace'?28+(value-min)/(max-min)*154:182-(value-min)/(max-min)*154;
  let d='',drawing=false;for(let i=0;i<activity.records.length;i++){const r=activity.records[i],v=seriesValue(r);if(v===null||!Number.isFinite(v)){drawing=false;continue;}if(i>0&&r.t-activity.records[i-1].t>30)drawing=false;d+=`${drawing?'L':'M'}${x(r).toFixed(2)},${y(v).toFixed(2)} `;drawing=true;}
  const value={min,max,end,x,y,d,left,span};chartCache={records:activity.records,value,series:state.series,width:innerWidth};return value;
}
function chartSvg(){
  const c=chartModel();if(!c)return '';
  const selected=state.selected===null?null:activity.blocks[state.selected];
  const cursor=state.cursor===null?null:activity.records[state.cursor];
  const unit=state.series==='pace'?'/km':state.series==='heart'?'bpm':'m';
  return `<svg viewBox="0 0 630 225" role="img" aria-label="${seriesName()} over elapsed time; ${state.selected===null?'full activity':`block ${state.selected+1} selected`}">${selected?`<rect class="chart-selection" x="${c.left+selected.start/c.end*c.span}" y="20" width="${selected.duration/c.end*c.span}" height="170"/>`:''}${[0,1,2].map(i=>{const v=c.min+(c.max-c.min)*i/2;const yy=c.y(v);return `<path class="chart-grid" d="M${c.left} ${yy}H598"/><text class="chart-label" x="${c.left-20}" y="${yy+4}" text-anchor="end">${state.series==='pace'?paceText(v):Math.round(v)}</text>`;}).join('')}<path class="chart-trace ${state.series}" d="${c.d}"/>${[0,1,2,3].map(i=>`<text class="chart-label" x="${c.left+c.span*i/3}" y="214" text-anchor="${i===0?'start':i===3?'end':'middle'}">${duration(c.end*i/3)}</text>`).join('')}<text class="chart-unit" x="${c.left}" y="12">${unit}</text><g class="chart-live-cursor">${cursor&&seriesValue(cursor)!==null?`<path class="chart-cursor-line" d="M${c.x(cursor)} 20V192"/><circle class="chart-cursor-dot" cx="${c.x(cursor)}" cy="${c.y(seriesValue(cursor))}" r="4"/>`:''}</g></svg>`;
}
function analysisPanel(){const hasRecords=activity.records.length>0;return `<section class="analysis-panel section" aria-labelledby="analysis-title"><div class="section-heading"><div><p class="section-caption">The shape of your session</p><h2 id="analysis-title">In the details</h2></div><button class="icon-button" data-action="method" aria-label="Chart calculation method">${icon('info')}</button></div>${hasRecords?`<div class="series-tabs" role="group" aria-label="Chart measurement">${[['pace','Pace'],['heart','Heart rate'],['elevation','Elevation']].map(([id,label])=>`<button data-series="${id}" aria-pressed="${state.series===id}" ${id==='heart'&&activity.hr===null?'disabled':''}>${label}</button>`).join('')}</div><div class="chart-readout"><span id="chart-time">${chartReadout().time}</span><strong id="chart-value">${chartReadout().value}</strong></div><div class="chart-canvas">${chartSvg()}</div><label class="chart-slider-label" for="chart-position">Inspect ${seriesName().toLowerCase()} by time</label><input id="chart-position" class="chart-slider" type="range" min="0" max="${activity.records.length-1}" value="${state.cursor??0}" aria-label="Inspect chart by time" aria-valuetext="${state.cursor===null?'Start of recorded session':duration(activity.records[state.cursor].t)}"><p class="chart-footnote">Elapsed time · unsmoothed recorded samples</p>`:`<div class="chart-empty">${icon('layers')}<h3>Chart data isn’t available.</h3><p>Your screenshots preserve the split values, but not the measurements behind this chart.</p></div>`}</section>`;}
function blocksPanel(){
  const historical=activity.records.length===0;
  const rows=historical?activity.splits||[]:activity.blocks;
  const body=rows.map((row,i)=>{
    const p=historical?row.paceSecondsPerKm:row.pace;
    const d=historical?(row.distanceM??row.displayedDistanceKm*1000):row.distance;
    const time=historical?(i<2?String(i+1):'Final'):`${duration(row.start)}<small>to ${duration(row.end)}</small>`;
    const label=`Block ${i+1}, ${duration(row.start)} to ${duration(row.end)}, ${d==null?'distance unavailable':Math.round(d)+' metres'}, pace ${paceText(p)} per kilometre, heart rate ${row.hr==null?'unavailable':round(row.hr)+' bpm'}`;
    return `<div class="block-row ${!historical&&state.selected===i?'selected':''}" role="row" ${!historical&&i>=6&&!state.expandedBlocks?'hidden':''} ${historical?'':`data-select-block="${i}"`}><span role="cell">${historical?time:`<button type="button" class="block-choice" data-block="${i}" aria-pressed="${state.selected===i}" aria-label="${label}">${time}</button>`}</span><span role="cell">${historical&&row.distanceM===null?'≈ ':''}${d==null?'—':Math.round(d)}<small>m</small></span><span role="cell" class="block-pace">${paceText(p)}<i class="pace-bar" style="--bar:${p?Math.max(15,Math.min(100,100-(p-300)/8)):15}%"></i></span><span role="cell">${historical?row.elevationChangeM:round(row.hr)}<small>${historical?'m':'bpm'}</small></span></div>`;
  }).join('');
  return `<section class="blocks-panel section" aria-labelledby="blocks-title"><div class="section-heading"><div><p class="section-caption">${historical?'From your screenshots':'Explore the recorded effort'}</p><h2 id="blocks-title">${historical?'Your splits':activity.blockLabel==='1-minute blocks'?'Minute by minute':'Time blocks'}</h2></div>${!historical?`<button class="text-button" data-action="clear-selection">Full activity</button>`:''}</div><p class="table-note">${historical?'Displayed kilometre paces. Final distance is rounded.':`${activity.blockLabel}. Select a row to link the route and chart.`}</p>${!historical&&rows.length>6?`<button class="text-button expand-blocks" data-action="expand-blocks" aria-expanded="${state.expandedBlocks}">${state.expandedBlocks?'Show fewer blocks':`Show all ${rows.length} blocks`}</button>`:''}<div class="block-table" role="table" aria-label="${historical?'Screenshot kilometre splits':'Sampled time blocks'}"><div class="block-row table-header" role="row"><span role="columnheader">${historical?'Kilometre':'Time'}</span><span role="columnheader">Distance</span><span role="columnheader">Pace /km</span><span role="columnheader">${historical?'Elev.':'HR¹'}</span></div>${body}</div>${!historical?`<p class="table-footnote">¹ Mean of available HR samples in each block.</p><details class="recorded-laps"><summary>Recorded laps <span>${activity.laps.length}</span>${icon('chevrondown')}</summary>${activity.laps.map((lap,i)=>`<div><span>Lap ${i+1}</span><strong>${distance(lap.distance)} km</strong><span>${duration(lap.duration)}</span></div>`).join('')}<p>Device laps; these need not be kilometre splits.</p></details>`:''}</section>`;
}
function sourceNote(){return activity.sourceNote?`<section class="source-note"><span class="section-kicker">Your original note</span><blockquote>${escape(activity.sourceNote)}</blockquote><p>From ${escape(activity.source)} · ${dateText(activity.date)}</p></section>`:'';}
const options={effort:Array.from({length:10},(_,i)=>[String(i+1),String(i+1)]),breathing:[['sentences','Sentences'],['phrases','Phrases'],['few-words','Few words']],discomfort:[['none','None'],['mild','Mild'],['affected','Affected the run']],finish:[['plenty','Plenty left'],['right','About right'],['limit','Near limit']]};
function question(name,title,description,number){return `<fieldset class="question" data-question="${name}"><legend><span class="question-number">${number}</span>${title}</legend>${description?`<p class="question-helper">${description}</p>`:''}<div class="choice-grid ${name==='effort'?'effort-grid':''}">${options[name].map(([value,label])=>`<label class="choice"><input type="radio" name="${name}" value="${value}" ${String(draft.answers[name])===value?'checked':''}><span>${name==='discomfort'&&value==='affected'&&activity.sport==='Walk'?'Affected the walk':label}</span></label>`).join('')}</div>${name==='effort'?'<div class="scale-labels"><span>Very easy</span><span>Maximum</span></div>':''}</fieldset>`;}
function feedbackForm(){
  if((draft.complete&&!['offline','save-error'].includes(state.scenario))||state.scenario==='success')return `<div class="checkin-complete"><span class="completion-symbol">${icon('check')}</span><p class="section-caption">${state.scenario==='success'?'Example completion state':'Your perspective, added'}</p><h2>Check-in preview complete.</h2><p>Your activity data is unchanged.<br>This demonstration stays in your browser.</p><button class="secondary-button" data-action="edit-feedback">Edit answers ${icon('arrow')}</button></div>`;
  const count=Object.values(draft.answers).filter(x=>x!==null).length;
  return `<form class="checkin-form" novalidate><div class="checkin-intro"><div><p class="section-caption">The part only you know</p><h2>How did this ${activity.sport==='Walk'?'walk':'run'} feel?</h2></div><span class="form-count">${count} of 4</span></div><p class="checkin-helper">Four quick answers. No right or wrong.</p><div class="form-progress" aria-hidden="true">${Object.values(draft.answers).map(x=>`<i class="${x!==null?'answered':''}"></i>`).join('')}</div>${question('effort','Whole-session effort','How hard did the session feel overall?',1)}${question('breathing','Could you hold a conversation?','',2)}${question('discomfort','Any discomfort?','',3)}<fieldset class="location-question question" ${!draft.answers.discomfort||draft.answers.discomfort==='none'?'hidden':''}><legend>Where did you feel it?</legend><div class="choice-grid location-grid">${['Shin','Knee','Ankle','Foot','Hip','Other'].map(label=>`<label class="choice"><input type="radio" name="location" value="${label.toLowerCase()}" ${draft.location===label.toLowerCase()?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>${question('finish','How did you finish?','',4)}<details class="optional-context" ${draft.note||draft.context.length?'open':''}><summary>Add context or a note <span>Optional</span>${icon('plus')}</summary><div class="context-chips">${['Heat','Poor sleep','Busy day','New shoes'].map(label=>`<button type="button" data-context="${label}" aria-pressed="${draft.context.includes(label)}">${label}</button>`).join('')}</div><label class="note-label">Anything else?<textarea name="note" maxlength="500" rows="3" placeholder="A detail you want to remember…">${escape(draft.note)}</textarea></label></details><p class="form-error" role="alert">${escape(state.feedbackError)}</p>${state.pending||draft.pending?`<div class="pending-message" role="status">${icon('cloud')}<div><strong>Pending in this preview</strong><p>Your answers are kept here. Retry to preview completion.</p><button type="button" class="text-button" data-action="retry-feedback">Retry check-in ${icon('refresh')}</button></div></div>`:''}<div class="form-actions"><span>Browser-only design preview</span><button type="submit" class="primary-button">Save check-in ${icon('check')}</button></div></form>`;
}
function inlineCheckin(){return `<section class="inline-checkin section" id="checkin" tabindex="-1">${feedbackForm()}</section>`;}
function connectionBanner(){if(!['expired','delayed','offline'].includes(state.scenario))return '';const text=state.scenario==='expired'?'Garmin connection expired. Imported activities are still here.':state.scenario==='delayed'?'New activities are delayed. Your last import is available.':'Offline preview. Your answers will stay in this browser.';return `<div class="connection-banner" role="status">${icon(state.scenario==='offline'?'cloud':'info')}<p>${text}</p>${state.scenario!=='offline'?`<button class="text-button" data-action="connection">${state.scenario==='expired'?'Review':'Retry'} ${icon('chevron')}</button>`:''}</div>`;}
function specialState(){
  if(state.scenario==='loading')return `<main id="main" class="special-state loading-state"><div class="skeleton long"></div><div class="skeleton title-skeleton"></div><div class="skeleton map-skeleton"></div><div class="skeleton long"></div><p>Loading your activity…</p><button class="secondary-button" data-action="normal">Show activity ${icon('arrow')}</button></main>`;
  if(state.scenario==='empty')return `<main id="main" class="special-state"><div class="empty-symbol">${icon('route')}</div><span class="section-caption">Your training log</span><h1>No activities<br>yet.</h1><p>Bring in an activity to inspect the details<br>and add your check-in.</p><button class="primary-button" data-action="normal">Explore a sample ${icon('arrow')}</button></main>`;
  if(state.scenario==='error')return `<main id="main" class="special-state"><div class="empty-symbol">${icon('cloud')}</div><span class="section-caption">Activity unavailable</span><h1>Let’s try<br>that again.</h1><p>This activity couldn’t load.<br>Your check-in draft is still here.</p><button class="primary-button" data-action="normal">Retry activity ${icon('refresh')}</button></main>`;
  return null;
}
function render(){
  premiumMotion?.destroy();
  if(activity.hr===null&&state.series==='heart')state.series='pace';
  document.body.dataset.theme='field-notes';document.body.className='field-notes fn-app';document.title=`${activity.title} — My Fitness Analyser`;
  const view=fieldNotesView({activity,icon,logo,dateText,distance,duration,paceText,summaryPace,escape,routePanel,stats,observationPanel,analysisPanel,blocksPanel,sourceNote,inlineCheckin,miniRoute:mapSvg('detail'),reduced:reducedMotion(),systemReduced:matchMedia('(prefers-reduced-motion:reduce)').matches});
  const special=specialState();
  $('#app').innerHTML=`<div class="app-shell"><div class="workspace">${special?view.slice(0,view.indexOf('<main id="main"'))+special:view}${connectionBanner()}<div class="mobile-dock"><div>${icon(draft.complete?'check':'journal')}<span>${draft.complete?'Check-in complete':'How did it feel?'}<small>${draft.complete?'Browser-only preview':'Four answers. About 30 seconds.'}</small></span></div><button class="primary-button" data-action="checkin">${draft.complete?'Edit':'Check-in'} ${icon('arrow')}</button></div></div></div>`;
  $('#dialogs').innerHTML=`<dialog id="sheet" class="feedback-sheet" aria-label="Quick check-in"><div class="sheet-handle" aria-hidden="true"></div><button class="icon-button close-dialog" data-action="close-dialog" aria-label="Close check-in">${icon('close')}</button><div class="sheet-body">${feedbackForm()}</div></dialog><dialog id="detail-dialog" class="detail-dialog"></dialog>`;
  if(!special)premiumMotion=mountPremiumMotion({records:activity.records,reduced:reducedMotion(),onCursor:updateCursor,onPreferenceChange:render});
}
function openDetail(title,html){premiumMotion?.stopReplay();const dialog=$('#detail-dialog');dialog.setAttribute('aria-label',title);dialog.innerHTML=`<header><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close details">${icon('close')}</button></header><div class="dialog-content">${html}</div>`;dialog.showModal();}
function openCheckin(){if(state.direction==='field-notes'&&!specialState()){const target=$('#checkin');target.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});target.focus({preventScroll:true});return;}$('#sheet').showModal();}
function refreshForm(){const sheetOpen=$('#sheet').open;$('.sheet-body').innerHTML=feedbackForm();if($('#checkin'))$('#checkin').innerHTML=feedbackForm();if(sheetOpen&&!$('#sheet').open)$('#sheet').showModal();const quick=$('.quick-card');if(quick)quick.outerHTML=quickCard();const dock=$('.mobile-dock');if(dock)dock.innerHTML=`<div>${icon(draft.complete?'check':'journal')}<span>${draft.complete?'Check-in complete':'How did it feel?'}<small>${draft.complete?'Browser-only preview':'Four answers. About 30 seconds.'}</small></span></div><button class="primary-button" data-action="checkin">${draft.complete?'Edit':'Check-in'} ${icon('arrow')}</button>`;}
function selectBlock(index){premiumMotion?.stopReplay();state.selected=index;state.cursor=null;updateExploration();$('#announcer').textContent=index===null?'Full activity selected':`Block ${index+1} selected in the route and chart.`;}
function updateExploration(){$$('.route-svg').forEach((svg,i)=>svg.innerHTML=mapSvg('view'+i));const chart=$('.chart-canvas');if(chart)chart.innerHTML=chartSvg();$$('[data-block]').forEach(b=>{b.setAttribute('aria-pressed',String(Number(b.dataset.block)===state.selected));b.closest('.block-row').classList.toggle('selected',Number(b.dataset.block)===state.selected);});$$('.route-selection').forEach(selection=>selection.textContent=state.selected===null?'Full activity':`Time block ${state.selected+1}`);const readout=chartReadout();if($('#chart-time'))$('#chart-time').textContent=readout.time;if($('#chart-value'))$('#chart-value').textContent=readout.value;}
function updateCursor(index){
  if(index<0||index>=activity.records.length)return;
  state.cursor=index;const row=activity.records[index],g=routeGeometry(),c=chartModel();
  const replayTime=$('#replay-time'),replayPace=$('#replay-pace'),replaySlider=$('#replay-position'),traceCursor=$('.fn-trace-cursor');
  if(replayTime)replayTime.textContent=duration(row.t);
  if(replayPace)replayPace.textContent=(row.speed>0?paceText(1000/row.speed)+' /km':'Pace unavailable');
  if(replaySlider){replaySlider.value=index;replaySlider.setAttribute('aria-valuetext',`${duration(row.t)}, ${replayPace?.textContent}`);}
  if(traceCursor)traceCursor.setAttribute('d',`M${row.t/activity.records.at(-1).t*600} 0V84`);
  const circle=(parent,cls,r)=>{let el=parent.querySelector('.'+cls);if(!el){el=document.createElementNS('http://www.w3.org/2000/svg','circle');el.setAttribute('class',cls);el.setAttribute('r',r);parent.append(el);}return el;};
  $$('[data-route-layer]').forEach(layer=>{if(!g||row.lat===null||row.lon===null){$$('.cursor-halo,.cursor-dot',layer).forEach(el=>el.remove());return;}const p=g.point(row);for(const [cls,r]of [['cursor-halo',10],['cursor-dot',4]]){const el=circle(layer,cls,r);el.setAttribute('cx',p.x);el.setAttribute('cy',p.y);}});
  const live=$('.chart-live-cursor');if(live&&c){const v=seriesValue(row);if(v===null){live.replaceChildren();}else{let line=$('.chart-cursor-line',live);if(!line){line=document.createElementNS('http://www.w3.org/2000/svg','path');line.setAttribute('class','chart-cursor-line');live.append(line);}line.setAttribute('d',`M${c.x(row)} 20V192`);const dot=circle(live,'chart-cursor-dot',4);dot.setAttribute('cx',c.x(row));dot.setAttribute('cy',c.y(v));}}
  const time=$('#chart-time'),value=$('#chart-value'),slider=$('#chart-position');if(time)time.textContent=duration(row.t)+' into session';if(value)value.textContent=state.series==='pace'?paceText(seriesValue(row))+' /km':state.series==='heart'?round(row.hr)+' bpm':round(row.elevation)+' m';if(slider){slider.value=index;slider.setAttribute('aria-valuetext',`${duration(row.t)}, ${value?.textContent}`);}}
function focusFeedbackResult(selector){const root=$('#sheet').open?$('#sheet'):$('#checkin');const result=root&&$(selector,root);if(result){result.tabIndex=-1;result.focus({preventScroll:true});result.scrollIntoView({block:'center',behavior:'instant'});}}
function saveFeedback(){
  if(['offline','save-error'].includes(state.scenario))draft.complete=false;
  const missing=Object.keys(draft.answers).find(key=>draft.answers[key]===null);
  if(missing){state.feedbackError='Answer the four questions to finish your check-in.';$$('.form-error').forEach(x=>x.textContent=state.feedbackError);const form=$('#sheet').open?$('#sheet'):$('#checkin');const question=$(`[data-question="${missing}"]`,form);question?.classList.add('missing');$('input',question)?.focus();return;}
  if(draft.answers.discomfort!=='none'&&!draft.location){state.feedbackError='Choose where you felt the discomfort.';$$('.form-error').forEach(x=>x.textContent=state.feedbackError);const root=$('#sheet').open?$('#sheet'):$('#checkin');$('.location-question input',root)?.focus();return;}
  if(state.scenario==='offline'){draft.pending=true;state.pending=true;state.feedbackError='';storeDraft();refreshForm();focusFeedbackResult('.pending-message');return;}
  if(state.scenario==='save-error'){state.feedbackError='Couldn’t complete the preview. Your answers are still here; try again.';state.scenario='normal';storeDraft();refreshForm();focusFeedbackResult('.form-error');return;}
  draft.complete=true;draft.pending=false;state.pending=false;state.feedbackError='';storeDraft();refreshForm();focusFeedbackResult('.checkin-complete h2');$('#announcer').textContent='Check-in preview complete. Your actual activity data has not changed.';
}
document.addEventListener('click',event=>{
  const block=event.target.closest('[data-block],[data-select-block]');if(block){const index=Number(block.dataset.block??block.dataset.selectBlock);selectBlock(state.selected===index?null:index);return;}
  const series=event.target.closest('[data-series]');if(series){premiumMotion?.stopReplay();state.series=series.dataset.series;const panel=$('.analysis-panel');panel.outerHTML=analysisPanel();$(`[data-series="${state.series}"]`)?.focus();return;}
  const choice=event.target.closest('[data-context]');if(choice){const context=choice.dataset.context;draft.context=draft.context.includes(context)?draft.context.filter(x=>x!==context):[...draft.context,context];choice.setAttribute('aria-pressed',String(draft.context.includes(context)));storeDraft();return;}
  const activityButton=event.target.closest('[data-activity]');if(activityButton){$('#detail-dialog').close();if(document.startViewTransition&&!reducedMotion())document.startViewTransition(()=>setActivity(activityButton.dataset.activity));else setActivity(activityButton.dataset.activity);return;}
  const target=event.target.closest('[data-action]');if(!target)return;
  const action=target.dataset.action;
  if(action==='checkin'){premiumMotion?.stopReplay();openCheckin();}
  if(action==='route-replay')premiumMotion?.toggleReplay();
  if(action==='motion'){document.documentElement.classList.toggle('reduce-motion');try{localStorage.setItem('mfa-visual-motion',document.documentElement.classList.contains('reduce-motion')?'off':'on');}catch{}render();}
  if(action==='close-dialog')target.closest('dialog').close();
  if(action==='source')openDetail('Where the details come from',`<div class="source-identity">${icon('layers')}<div><h3>${escape(activity.source)}</h3><p>${escape(activity.device)}</p></div></div><dl><div><dt>Recorded date</dt><dd>${dateText(activity.date)}</dd></div>${activity.running!=null?`<div><dt>Running time</dt><dd>${duration(activity.running)}</dd></div>`:''}<div><dt>Timer time</dt><dd>${duration(activity.timer)}</dd></div><div><dt>Moving time</dt><dd>${duration(activity.moving)}</dd></div><div><dt>Elapsed time</dt><dd>${duration(activity.elapsed)}</dd></div><div><dt>GPS samples</dt><dd>${activity.records.filter(r=>r.lat!==null&&r.lon!==null).length||'Not available'}</dd></div></dl><p>${activity.synthetic?'This is generated demonstration data.':activity.records.length?'The original FIT and Garmin summary were inspected together. This preview uses a local capture, not a live refresh.':'Transcribed from your screenshots. Missing sensor data stays missing.'}</p><p>${activity.records.length?'The route follows available GPS samples, without map tiles. Missing GPS stays missing. Charts are unsmoothed; HR in time blocks is a sample mean.':'Your screenshots preserve displayed summaries and splits. No GPS or chart series is reconstructed, and rounded distances stay approximate.'}</p>${activity.sourceFile==='Owner-supplied screenshots'?`<button class="secondary-button" data-action="evidence">View source screenshots ${icon('layers')}</button>`:''}${activity.sourceIssues.length?`<details><summary>Source details to retain</summary><ul>${activity.sourceIssues.map(x=>`<li>${escape(x)}</li>`).join('')}</ul></details>`:''}`);
  if(action==='evidence'){const images=activity.id==='nrc'?[4,5,6]:[1,2,3];$('#detail-dialog').close();openDetail('Your original screenshots',`<p>Source images only. No GPS or chart series has been reconstructed.</p>${images.map(id=>`<figure class="evidence-image"><img src="/api/evidence/${id}" alt="Original ${escape(activity.source)} screenshot ${id}"><figcaption>Owner-supplied source image ${id}</figcaption></figure>`).join('')}`);}
  if(action==='method')openDetail('A finding you can inspect',`<p class="method-finding">${escape(activity.observation.title)}</p><p>${escape(activity.observation.method)}</p><p>Time blocks follow recorded timestamps, so the final block may be shorter. Recorded device laps are shown separately.</p><p>No readiness, injury risk or fitness improvement is inferred.</p>`);
  if(action==='activities')openDetail('Your activity samples',`<p class="dialog-intro">Your imported activities and the labelled design sample.</p><div class="activity-list">${payload.activities.map(a=>`<button data-activity="${a.id}" class="activity-option ${a.id===activity.id?'current':''}"><span class="activity-icon">${icon('route')}</span><span><strong>${escape(a.title)}</strong><small>${dateText(a.date)} · ${escape(a.source)}</small></span><span>${distance(a.distance)}<small>km</small></span>${icon('chevron')}</button>`).join('')}</div>`);
  if(action==='zoom-in'||action==='zoom-out'){state.zoom=Math.max(.8,Math.min(2,state.zoom+(action==='zoom-in' ? .2 : -.2)));updateExploration();}
  if(action==='fit-route'){state.zoom=1;updateExploration();}
  if(action==='clear-selection')selectBlock(null);
  if(action==='expand-blocks'){state.expandedBlocks=!state.expandedBlocks;$$('[data-select-block]').forEach(row=>row.hidden=Number(row.dataset.selectBlock)>=6&&!state.expandedBlocks);target.setAttribute('aria-expanded',String(state.expandedBlocks));target.textContent=state.expandedBlocks?'Show fewer blocks':`Show all ${activity.blocks.length} blocks`;if(!state.expandedBlocks&&state.selected>=6)selectBlock(null);}
  if(action==='normal'){state.scenario='normal';activity=currentActivity();render();}
  if(action==='edit-feedback'){state.scenario='normal';draft.complete=false;storeDraft();refreshForm();}
  if(action==='retry-feedback'){state.scenario='normal';saveFeedback();}
  if(action==='connection')openDetail(state.scenario==='expired'?'Reconnect Garmin':'Import status',`<p>${state.scenario==='expired'?'Your imported activities are still available. In the finished app, reconnecting will restore new imports.':'The last imported activity is available. In the finished app, this will show the last attempt and a retry action.'}</p><button class="primary-button" data-action="connection-preview">Return to connected preview ${icon('check')}</button>`);
  if(action==='connection-preview'){state.scenario='normal';$('#detail-dialog').close();render();}
  if(action==='reset-demo'&&activity.synthetic){draft=emptyDraft();state.scenario='normal';state.pending=false;state.feedbackError='';storeDraft();$('#detail-dialog').close();render();}
  if(action==='review')openDetail('Review this direction',`<p>Field Notes design preview. Check-ins stay in this browser.</p><button class="secondary-button" data-action="motion" ${matchMedia('(prefers-reduced-motion:reduce)').matches?'disabled':''}>${reducedMotion()?'Enable visual motion':'Reduce visual motion'}</button>${activity.synthetic?`<button class="secondary-button" data-action="reset-demo">Reset demo check-in</button>`:''}<label class="review-state-label">Interface state<select id="local-scenario">${[['normal','Recorded activity'],['partial','Missing GPS & HR'],['empty','No activities'],['loading','Loading'],['error','Load failed'],['save-error','Check-in retry'],['offline','Offline / pending'],['delayed','Sync delayed'],['expired','Key expired'],['success','Completion preview']].map(([v,l])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${l}</option>`).join('')}</select></label><a class="secondary-button" href="/studio">Open design studio ${icon('arrow')}</a>`);
});
document.addEventListener('change',event=>{
  const input=event.target;
  if(input.matches('.checkin-form input[type=radio]')){
    if(input.name==='location')draft.location=input.value;else draft.answers[input.name]=input.value;
    if(input.name==='discomfort'&&input.value==='none'){draft.location=null;$$('input[name="location"]').forEach(x=>x.checked=false);}
    state.feedbackError='';input.closest('.question')?.classList.remove('missing');
    $$('.location-question').forEach(x=>x.hidden=!draft.answers.discomfort||draft.answers.discomfort==='none');
    const count=Object.values(draft.answers).filter(x=>x!==null).length;$$('.form-count').forEach(x=>x.textContent=`${count} of 4`);$$('.form-progress').forEach(progress=>[...progress.children].forEach((x,i)=>x.classList.toggle('answered',Object.values(draft.answers)[i]!==null)));$$('.form-error').forEach(x=>x.textContent='');storeDraft();
  }
  if(input.id==='local-scenario'){state.scenario=input.value;activity=currentActivity();$('#detail-dialog').close();render();}
});
document.addEventListener('input',event=>{if(event.target.name==='note'){draft.note=event.target.value;storeDraft();}if(['chart-position','replay-position'].includes(event.target.id)){premiumMotion?.stopReplay();updateCursor(Number(event.target.value));}});
document.addEventListener('submit',event=>{if(event.target.matches('.checkin-form')){event.preventDefault();saveFeedback();}});
document.addEventListener('pointermove',event=>{const chart=event.target.closest('.chart-canvas');if(!chart||event.pointerType==='touch')return;pointerX=event.clientX;premiumMotion?.stopReplay();if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;if(!chart.isConnected)return;const rect=chart.getBoundingClientRect(),portion=(pointerX-rect.left)/rect.width,c=chartModel();if(!c)return;const i=Math.round(Math.max(0,Math.min(1,(portion*630-c.left)/c.span))*(activity.records.length-1));updateCursor(i);});});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);const next=p.get('activity')||payload.defaultId;if(next===state.activityId)return;state.activityId=next;state.selected=null;state.cursor=null;state.zoom=1;activity=currentActivity();draft=readDraft();render();});
window.addEventListener('storage',event=>{if(event.key==='mfa-prototype:'+activity.id&&!$('#sheet').open){draft=readDraft();refreshForm();}});
try{payload=await fetch('/api/data').then(r=>{if(!r.ok)throw new Error('Unavailable');return r.json();});state.activityId||=payload.defaultId;activity=currentActivity();draft=readDraft();state.pending=draft.pending;render();}catch{$('#app').innerHTML='<main class="special-state"><h1>The preview couldn’t load.</h1><p>Restart the local prototype server, then reload this page.</p></main>';}
